// Parse the LLM output (may be object OR string - see project rule 15)
const raw = $input.first().json.message?.content ?? $input.first().json;
const p = typeof raw === 'string' ? JSON.parse(raw) : raw;
const ctx = $('From Telegram').first().json;

// Zone and the default time windows come from Config, so a user changes them
// in one visible place instead of editing code.
const cfg = $('⚙️ Config').first().json || {};
const ZONE = String(cfg.timezone || 'Europe/Berlin');
function win(label, spec, fallback) {
  const m = String(spec || '').match(/^\s*(\d{1,2}:\d{2})\s*-\s*(\d{1,2}:\d{2})\s*$/);
  if (m) return { label, start: m[1], end: m[2] };
  const f = String(fallback).split('-');
  return { label, start: f[0], end: f[1] };
}
const DEFAULT_WINDOWS = [
  win('Morning', cfg.morning_window, '07:00-09:00'),
  win('Lunch',   cfg.lunch_window,   '13:00-14:00'),
  win('Dinner',  cfg.dinner_window,  '19:00-21:00')
];

let start = DateTime.fromISO(String(p.start_date || ''), { zone: ZONE });
if (!start.isValid) start = DateTime.now().setZone(ZONE);
let end = DateTime.fromISO(String(p.end_date || ''), { zone: ZONE });
if (!end.isValid) end = start.plus({ days: 6 });
if (end < start) end = start;
// hard clamp: never scan more than 14 days
if (end.diff(start, 'days').days > 13) end = start.plus({ days: 13 });

let windows = Array.isArray(p.windows) && p.windows.length ? p.windows : DEFAULT_WINDOWS;
windows = windows
  .filter(w => w && /^\d{1,2}:\d{2}$/.test(String(w.start)) && /^\d{1,2}:\d{2}$/.test(String(w.end)))
  .slice(0, 6);
if (!windows.length) windows = DEFAULT_WINDOWS;

const minMinutes = Math.max(5, Math.min(240, parseInt(p.min_minutes, 10) || Number(cfg.min_slot_minutes) || 30));

return [{ json: {
  chat_id: ctx.chat_id,
  language: ctx.language || 'en',
  user_id: ctx.user_id,
  original_text: ctx.text,
  start_date: start.toFormat('yyyy-MM-dd'),
  end_date: end.toFormat('yyyy-MM-dd'),
  windows,
  min_minutes: minMinutes,
  timeMin: start.startOf('day').toISO(),
  timeMax: end.endOf('day').toISO()
} }];

const ctx = $('Normalize Range').first().json;
const ZONE = 'Europe/Berlin';

// The Google Calendar availability node returns different shapes across versions.
// Accept all of them rather than assume one.
const busy = [];
for (const item of $input.all()) {
  const r = item.json || {};
  if (Array.isArray(r.busy)) busy.push(...r.busy);
  else if (r.start && r.end) busy.push({ start: r.start, end: r.end });
  else if (r.calendars && typeof r.calendars === 'object') {
    for (const k of Object.keys(r.calendars)) {
      const b = r.calendars[k] && r.calendars[k].busy;
      if (Array.isArray(b)) busy.push(...b);
    }
  }
}

const iv = busy
  .map(b => ({ s: DateTime.fromISO(String(b.start)).toMillis(), e: DateTime.fromISO(String(b.end)).toMillis() }))
  .filter(b => Number.isFinite(b.s) && Number.isFinite(b.e) && b.e > b.s)
  .sort((a, b) => a.s - b.s);

// merge overlapping busy blocks
const merged = [];
for (const b of iv) {
  const last = merged[merged.length - 1];
  if (last && b.s <= last.e) last.e = Math.max(last.e, b.e);
  else merged.push({ s: b.s, e: b.e });
}

const minMs = (ctx.min_minutes || 30) * 60000;
const nowMs = DateTime.now().setZone(ZONE).toMillis();
const days = [];
let cursor = DateTime.fromISO(ctx.start_date, { zone: ZONE }).startOf('day');
const last = DateTime.fromISO(ctx.end_date, { zone: ZONE }).startOf('day');

let guard = 0;
while (cursor <= last && guard++ < 21) {
  const day = { date: cursor.toFormat('yyyy-MM-dd'), label: cursor.toFormat('cccc, d LLL'), windows: [] };
  for (const w of ctx.windows) {
    const [sh, sm] = String(w.start).split(':').map(Number);
    const [eh, em] = String(w.end).split(':').map(Number);
    const wStart = cursor.set({ hour: sh, minute: sm || 0, second: 0, millisecond: 0 }).toMillis();
    const wEnd   = cursor.set({ hour: eh, minute: em || 0, second: 0, millisecond: 0 }).toMillis();
    if (!(wEnd > wStart)) continue;

    let free = [{ s: wStart, e: wEnd }];
    for (const b of merged) {
      const next = [];
      for (const f of free) {
        if (b.e <= f.s || b.s >= f.e) { next.push(f); continue; }
        if (b.s > f.s) next.push({ s: f.s, e: Math.min(b.s, f.e) });
        if (b.e < f.e) next.push({ s: Math.max(b.e, f.s), e: f.e });
      }
      free = next;
    }

    const slots = free
      .map(f => ({ s: Math.max(f.s, nowMs), e: f.e }))       // drop time already past
      .filter(f => (f.e - f.s) >= minMs)
      .map(f => ({
        start: DateTime.fromMillis(f.s).setZone(ZONE).toFormat('HH:mm'),
        end:   DateTime.fromMillis(f.e).setZone(ZONE).toFormat('HH:mm'),
        minutes: Math.round((f.e - f.s) / 60000)
      }));

    day.windows.push({ label: w.label, start: w.start, end: w.end, slots });
  }
  days.push(day);
  cursor = cursor.plus({ days: 1 });
}

const totalSlots = days.reduce((a, d) => a + d.windows.reduce((x, w) => x + w.slots.length, 0), 0);
return [{ json: { ...ctx, days, totalSlots, busy_blocks: merged.length } }];

const ctx = $('Compute Free Slots').first().json;
const de = ctx.language === 'de';

// Rule 22: emit only tags WE control, escape every dynamic value.
const esc = s => String(s == null ? '' : s).replace(/<br\s*\/?>/gi,'\n').replace(/<\/?p>/gi,'\n')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const lines = [];
lines.push('<b>' + (de ? 'Freie Zeiten' : 'Free time') + '</b>  ' + esc(ctx.start_date) + ' - ' + esc(ctx.end_date));
lines.push('');

let any = false;
for (const d of ctx.days) {
  const dayLines = [];
  for (const w of d.windows) {
    if (!w.slots.length) continue;
    any = true;
    dayLines.push('  • ' + esc(w.label) + ': ' + w.slots.map(s => esc(s.start) + ' - ' + esc(s.end)).join(', '));
  }
  if (dayLines.length) {
    lines.push('<b>' + esc(d.label) + '</b>');
    lines.push(...dayLines);
    lines.push('');
  }
}

if (!any) {
  lines.push(de ? 'Keine freien Slots in diesen Fenstern.' : 'No free slots in those windows.');
  lines.push('');
}

lines.push('<i>' + (de ? 'Fenster' : 'Windows') + ': ' +
  ctx.windows.map(w => esc(w.label) + ' ' + esc(w.start) + ' - ' + esc(w.end)).join('  |  ') + '</i>');
lines.push('<i>Europe/Berlin</i>');

// Rule 19: Telegram hard-caps a message at 4096 chars.
let text = lines.join('\n');
const MAX = 3800;
if (text.length > MAX) text = text.slice(0, MAX) + '\n…(truncated)';

return [{ json: { ...ctx, message: text, preview: text.replace(/<[^>]+>/g, '').slice(0, 300) } }];

// Restore the real payload after the progress ack.
//
// This ack used to be a terminal FORK. n8n gives forked terminal nodes NO
// ordering guarantee - a measured case in this project ran 131 SECONDS late,
// after the result it was meant to precede. In series the order is guaranteed,
// but a Telegram send outputs the Telegram API response instead of its input
// (rule 18), so the next node would read whatever Telegram returned.
//
// Two things here were verified against live probes before this was rolled out,
// not assumed:
//   .all() is called with NO branch argument on purpose. It resolves to the
//   branch that feeds THIS node, so it stays correct when the ack hangs off an
//   IF's false output, and it survives the ack collapsing many items to one.
//   An explicit index would have to be kept in sync with the wiring; this does
//   not.
//
//   Referencing a node that did not execute THROWS (n8n wraps it oddly, as
//   "Cannot assign to read only property 'name'", which reads like something
//   else entirely). A node that simply has not run YET can instead return []
//   silently. The loop below tolerates both: it tries each candidate and takes
//   the first non-empty result, so it cannot be fooled by either failure mode.
//   $() with a variable works, which is what lets this be a loop.
const SRCS = ['From Telegram'];
let items = [];
for (const s of SRCS) {
  try {
    const r = $(s).all();
    if (r && r.length) { items = r; break; }
  } catch (e) { /* that path did not run in this execution */ }
}
if (!items.length) throw new Error('Restore Ctx: no upstream in ' + SRCS.join(' / ') + ' produced items');
return items.map(i => ({ json: i.json }));

// Normalises a Telegram update, text or transcribed voice, into the single
// shape the rest of the workflow expects.
//
// It falls back to its own input rather than hard-referencing the trigger, so
// the node stays drivable from a test webhook. A bare $('Telegram Trigger')
// reference would throw on any path where the trigger did not run.
let msg = null;
try { msg = $('Telegram Trigger').first().json.message; } catch (e) {}
if (!msg) msg = ($input.first().json || {}).message || {};

// A text message carries its own text. A voice note arrives here after the
// transcription node, so the text is on this node's input instead.
let text = String(msg.text || '').trim();
if (!text) {
  const t = $input.first().json || {};
  text = String(t.text || t.transcription || '').trim();
}

const cfg = $('⚙️ Config').first().json || {};
const chat = String((msg.chat && msg.chat.id) || cfg.default_chat_id || '');

// Cheap EN/DE pick so the ack and the answer come back in the language asked.
// Only German tokens that are NOT also English words, otherwise plain English
// gets flagged as German.
const de = /[\u00e4\u00f6\u00fc\u00df]/i.test(text)
  || /\b(wann|frei|zeit|termin|woche|uhr|morgen|heute|naechste|nächste)\b/i.test(text);

return [{ json: { action: 'invoke', chat_id: chat, language: de ? 'de' : 'en', text } }];
